// ⭐ D149 RULE 3 · the side-by-sides exist for every screen built so far, at both sizes, with a similarity score —
// generated by scripts/fidelityShots.mjs (sketch vs app, Dusk Dark, 1280 × 800 and 390 × 844). The owner signs each off.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";

const DIR = "docs/fidelity-shots";
const SCREENS = ["deck", "fullhouse", "settings"];

test("d149FidelityShotsGenerated · every screen × both sizes: the sketch, the app, the side-by-side, and a score", () => {
  const report = JSON.parse(fs.readFileSync(`${DIR}/fidelity.json`, "utf8"));
  for (const s of SCREENS) for (const size of ["desktop", "phone"]) {
    for (const kind of ["sketch", "app", "side"]) {
      const f = `${DIR}/${s}-${kind}-${size}.png`;
      assert.ok(fs.existsSync(f) && fs.statSync(f).size > 5000, `${f} is missing or empty`);
    }
    const r = report[`${s}-${size}`];
    assert.ok(r && r.similarity > 0 && r.similarity <= 1, `${s}-${size} has no similarity score`);
    assert.ok(Array.isArray(r.worstRegions), `${s}-${size} lists its differing regions`);
  }
  const src = fs.readFileSync("scripts/fidelityShots.mjs", "utf8");
  assert.match(src, /const SIZES = \{ desktop: \[1280, 800\], phone: \[390, 844\] \};/);
  assert.match(src, /localStorage\.setItem\("draft-theme", "dusk-dark"\)/, "the app side is shot in Dusk Dark");
});
